	eta.logger.For(ctx).Info("Dispatch successful",
		zap.String("driverID", resp.DriverID),
		zap.String("eta", resp.ETA.String()),
		zap.Float64("fare", resp.Fare),
''')
open(p,'w').write(s)
p='services/driver/consumer.go'
s=open(p).read()
s=s.replace('''fmt.Sprintf("Driver %s arriving in %s", bestDriver.DriverID, bestDriver.ETA.String()),''','''fmt.Sprintf("Driver %s arriving in %s. Fare: $%.2f",
