package driver

import (
	"testing"
	"time"
)

func TestComputeFare(t *testing.T) {
	tests := []struct {
		eta  time.Duration
		want float64
	}{
		{0, 3.50},
		{time.Minute, 3.50},
		{2 * time.Minute, 3.50},
		{2*time.Minute + 20*time.Second, 3.50},
		{2*time.Minute + 30*time.Second, 3.75},
		{10 * time.Minute, 15.00},
		{3*time.Minute + 20*time.Second, 5.00},
	}
	for _, tt := range tests {
		if got := computeFare(tt.eta); got != tt.want {
			t.Errorf("computeFare(%s) = %.2f, want %.2f", tt.eta, got, tt.want)
		}
	}
}
EOF
