// isMissingTable reports whether err is MySQL's "Table doesn't exist".
func isMissingTable(err error) bool {
	mysqlErr, ok := err.(*mysql.MySQLError)
	return ok && mysqlErr.Number == 1146
}

// execRideHistory runs a statement, creating the ride_history table and
// retrying once if it does not exist yet.
func (d *database) execRideHistory(query string, args ...interface{}) (sql.Result, error) {
	res, err := d.db.Exec(query, args...)
	if err != nil && isMissingTable(err) {
		if err = d.setupRideHistory(); err != nil {
			return nil, err
		}
		res, err = d.db.Exec(query, args...)
	}
	return res, err
}

func (d *database) ListRideHistory(ctx context.Context) (*RideHistoryResponse, error) {
	d.logger.For(ctx).Info("Loading ride history")

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.Key("sql.query").String("SELECT ... FROM ride_history"),
	)
	defer span.End()

	query := "SELECT id, pickup_name, dropoff_name, request_time, driver_plate, fare " +
		"FROM ride_history ORDER BY request_time DESC, id DESC LIMIT ?"
	rows, err := d.db.Query(query, maxRideHistory)
	if err != nil && isMissingTable(err) {
		if err = d.setupRideHistory(); err != nil {
			return nil, err
		}
		rows, err = d.db.Query(query, maxRideHistory)
	}
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	resp := &RideHistoryResponse{Rides: []RideHistoryEntry{}}
