		entry.PickupName, entry.DropoffName, requestTime.UTC(), nullString(entry.DriverPlate), entry.Fare)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	return d.getRideHistory(id)
}

// UpdateRideHistory sets the driver plate and fare of an existing entry. It
// returns sql.ErrNoRows if the entry does not exist.
func (d *database) UpdateRideHistory(ctx context.Context, update *RideHistoryUpdate) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Updating ride history entry", zap.Int64("id", update.ID))

	if _, err := d.execRideHistory("UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?",
		nullString(update.DriverPlate), update.Fare, update.ID); err != nil {
		return nil, err
	}
	// RowsAffected is 0 when the values are unchanged, so look the entry up
	return d.getRideHistory(update.ID)
}

func (d *database) getRideHistory(id int64) (*RideHistoryEntry, error) {
	row := d.db.QueryRow("SELECT id, pickup_name, dropoff_name, request_time, driver_plate, fare "+
		"FROM ride_history WHERE id = ?", id)
	return scanRideHistory(row)
}

