func (d *database) CreateRideHistory(ctx context.Context, entry *RideHistoryEntry) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Creating ride history entry")

	requestTime := entry.RequestTime
	if requestTime.IsZero() {
		requestTime = time.Now()
	}
	res, err := d.execRideHistory(
		"INSERT INTO ride_history SET pickup_name = ?, dropoff_name = ?, request_time = ?, driver_plate = ?, fare = ?",
		entry.PickupName, entry.DropoffName, requestTime.UTC(), nullString(entry.DriverPlate), entry.Fare)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	return d.getRideHistory(id)
