func (d *database) UpdateRideHistory(ctx context.Context, update *RideHistoryUpdate) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Updating ride history entry", zap.Int64("id", update.ID))

	if _, err := d.execRideHistory("UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?",
