cat > src/utils/driverNotification.ts <<'EOF'
export type DriverAssignment = {
    plate: string,
    fare: number,
}

// The driver service reports the assignment as
// "Driver <plate> arriving in <eta>. Fare: $<amount>"
const driverAssignmentRegex = /Driver\s+(.*?)\s+arriving in .*?Fare:\s*\$(\d+(?:\.\d+)?)/;

export const parseFare = (status: string): number | undefined => {
    const match = status.match(/Fare:\s*\$(\d+(?:\.\d+)?)/);
    return match ? parseFloat(match[1]) : undefined;
};

export const parseDriverAssignment = (status: string): DriverAssignment | undefined => {
    const match = status.match(driverAssignmentRegex);
    if (!match) return undefined;
    return {plate: match[1], fare: parseFloat(match[2])};
};

export const formatFare = (fare: number) => `$${fare.toFixed(2)}`;
EOF
