async (page) => {
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.unrouteAll();
  await page.route('**/*', async route => {
    await route.continue({ headers: { ...route.request().headers(), 'baggage': route.request().headers()['baggage'] ? route.request().headers()['baggage'] + ',sd-routing-key=v55cvk6vlvj6d' : 'sd-routing-key=v55cvk6vlvj6d', 'tracestate': 'sd-routing-key=v55cvk6vlvj6d' } });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  await page.getByRole('combobox').first().selectOption('1');
  await page.getByRole('combobox').nth(1).selectOption('123');
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.getByText(/Estimated fare/).waitFor({ timeout: 30000 });
  await page.waitForTimeout(3000);
  const body = await page.locator('body').innerText();
  return { countdown: await page.getByText(/will arrive in/).first().innerText(), history: await page.getByTestId('ride-history').innerText(), len: (await page.content()).length, errors };
}

